-- AdventureAtlas / Core / Knowledge.lua
--
-- The knowledge base data: the quests of World of Warcraft: Forever, delivered by the load-on-demand
-- addon AdventureAtlas_Knowledge (generated by tools/gen_knowledge_data.lua; its header documents the
-- record fields) through AdventureAtlas.AddKnowledge. Loaded the first time the atlas tab asks for it
-- (Knowledge:Load), then searched in memory (Knowledge:Search). Names in the data are enUS: quest titles
-- come from the client cache when it has them (localized), zone names from C_Map / the class name from
-- C_CreatureInfo, NPC and object names stay enUS.
--
-- Exposes ns.Knowledge and the public AdventureAtlas.AddKnowledge.

-- luacheck: ignore 212/self (singleton module keeps the colon method style)

local _, ns = ...

local type, pairs, ipairs, tostring = type, pairs, ipairs, tostring
local floor, sort = math.floor, table.sort

local Knowledge = {}
ns.Knowledge = Knowledge

Knowledge.ADDON = "AdventureAtlas_Knowledge"

-- class file -> classID (C_CreatureInfo.GetClassInfo gives the localized name)
local CLASS_IDS = {
    WARRIOR = 1, PALADIN = 2, HUNTER = 3, ROGUE = 4, PRIEST = 5, SHAMAN = 7, MAGE = 8, WARLOCK = 9, DRUID = 11,
}
-- race bits of the data's race masks (the DB snapshot: Skyborne has one bit per faction, above 2^32)
local RACE_BITS = {
    Human = 1, Orc = 2, Dwarf = 4, NightElf = 8, Scourge = 16, Tauren = 32, Gnome = 64, Troll = 128, Goblin = 256,
    Skyborne = { Alliance = 2 ^ 32, Horde = 2 ^ 33 },
}
local CLASS_BITS = {
    WARRIOR = 1, PALADIN = 2, HUNTER = 4, ROGUE = 8, PRIEST = 16, SHAMAN = 64, MAGE = 128, WARLOCK = 256, DRUID = 1024,
}

-- Masks exceed 32 bits: test with arithmetic, never bit.band.
local function hasBit(mask, b)
    return b ~= nil and floor(mask / b) % 2 == 1
end

--- Lower case for search: ASCII plus the Cyrillic capitals (string.lower leaves UTF-8 alone).
local function lowerText(s)
    s = s:lower()
    s = s:gsub("\208([\144-\159])", function(c) return "\208" .. string.char(c:byte() + 32) end) -- А-П
    s = s:gsub("\208([\160-\175])", function(c) return "\209" .. string.char(c:byte() - 32) end) -- Р-Я
    return (s:gsub("\208\129", "\209\145")) -- Ё
end
Knowledge.LowerText = lowerText

--- Store the data of AdventureAtlas_Knowledge (one call). Builds the level-sorted id list; adds the
-- run-time fields lname (lowered enUS name) and ltsrc / ltitle (cached localized title, lowered) to records.
function Knowledge:Add(data)
    if type(data) ~= "table" or type(data.quests) ~= "table" then
        ns.Print("%s", "AddKnowledge: no quests table")
        return false
    end
    self.data = data
    local ids = {}
    for id, q in pairs(data.quests) do
        ids[#ids + 1] = id
        q.lname = lowerText(q.n or "")
    end
    local quests = data.quests
    sort(ids, function(a, b)
        local qa, qb = quests[a], quests[b]
        if qa.l ~= qb.l then return qa.l < qb.l end
        if qa.n ~= qb.n then return qa.n < qb.n end
        return a < b
    end)
    self.ids = ids
    return true
end

ns.public.AddKnowledge = function(data) return Knowledge:Add(data) end

function Knowledge:IsLoaded() return self.data ~= nil end

--- Load AdventureAtlas_Knowledge if needed. @return true, or false + the client's reason ("MISSING",
-- "DISABLED", ...)
function Knowledge:Load()
    if self.data then return true end
    local reason
    if C_AddOns and C_AddOns.LoadAddOn then
        local ok, loaded, why = pcall(C_AddOns.LoadAddOn, self.ADDON)
        if not ok then reason = "ERROR" elseif not loaded then reason = why end
    end
    if self.data then return true end
    return false, reason or "MISSING"
end

function Knowledge:Get(id) return self.data and self.data.quests[id] end

--- Quest title: localized from the client cache when known (asks for it otherwise), else enUS.
function Knowledge:Title(id)
    local q = self:Get(id)
    local t = ns.Compat.GetQuestTitle(id)
    return t or (q and q.n) or tostring(id)
end

--- Localized name of a zone key of the data.
function Knowledge:ZoneName(key)
    local z = self.data and self.data.zones[key]
    if not z then return "" end
    local C = ns.Compat
    local name
    if z.map then name = C.GetMapName(z.map) end
    if not name and z.area then name = C.AreaName(z.area) end
    if not name and z.class then
        local ok, info = pcall(C_CreatureInfo.GetClassInfo, CLASS_IDS[z.class] or 0)
        name = ok and type(info) == "table" and info.className or z.class
    end
    if not name then name = (ns.locale == "ruRU" and z.ru) or z.en or "" end
    return name
end

--- Name and position of an NPC / object of the data. @return name, map, x, y (no position: name only)
function Knowledge:Entity(kind, id)
    local t = self.data and self.data[kind == "o" and "objects" or "npcs"]
    local e = t and t[id]
    if not e then return nil end
    return e[1], e[2], e[3], e[4]
end

function Knowledge:ItemName(id)
    local items = self.data and self.data.items
    return (items and items[id]) or ns.Compat.ItemName(id)
end

--- Can a character of this race / class / faction take the quest (levels aside)?
function Knowledge:IsFor(q, facts)
    if self.data and self.data.faction and facts.faction and facts.faction ~= self.data.faction then return false end
    if q.ra then
        local b = RACE_BITS[facts.race or ""]
        if type(b) == "table" then b = b[facts.faction or ""] end
        if not hasBit(q.ra, b) then return false end
    end
    if q.cl and not hasBit(q.cl, CLASS_BITS[facts.class or ""]) then return false end
    return true
end

--- "done" (turned in), "active" (in the log) or nil.
function Knowledge:Status(id)
    local C = ns.Compat
    if C.IsQuestTurnedIn(id) then return "done" end
    if C.IsOnQuest(id) then return "active" end
    return nil
end

--- Ids of the quests that match, in level order.
-- filter = { text = "...", minLevel = n, maxLevel = n, mine = bool, hideDone = bool, onlyNew = bool }
-- text matches the enUS name, the cached localized title or the zone name (case-insensitive); quests
-- without a fixed level (l <= 0) pass any level range.
function Knowledge:Search(filter)
    local out = {}
    if not self.data then return out end
    filter = filter or {}
    local text = filter.text and filter.text ~= "" and lowerText(filter.text) or nil
    local facts = filter.mine and ns.Compat.PlayerFacts() or nil
    local quests = self.data.quests
    local zoneText = {}
    for _, id in ipairs(self.ids) do
        local q = quests[id]
        local ok = true
        if filter.onlyNew and not q.new then ok = false end
        if ok and filter.minLevel and q.l > 0 and q.l < filter.minLevel then ok = false end
        if ok and filter.maxLevel and q.l > filter.maxLevel then ok = false end
        if ok and facts and not self:IsFor(q, facts) then ok = false end
        if ok and text then
            local found = q.lname:find(text, 1, true)
            if not found then
                local t = ns.Compat.GetCachedQuestTitle(id)
                if t and t ~= q.ltsrc then q.ltsrc, q.ltitle = t, lowerText(t) end -- lowered once per title
                found = t and q.ltitle:find(text, 1, true)
            end
            if not found then
                local zt = zoneText[q.z]
                if not zt then
                    zt = lowerText(self:ZoneName(q.z))
                    zoneText[q.z] = zt
                end
                found = zt:find(text, 1, true)
            end
            ok = found and true or false
        end
        if ok and filter.hideDone and ns.Compat.IsQuestTurnedIn(id) then ok = false end
        if ok then out[#out + 1] = id end
    end
    return out
end
